/* eslint-disable @next/next/no-img-element -- small static SVG logos; next/image adds nothing here */
import logos from "@/lib/tool-logos.json";

/* Full-colour brand logos generated by scripts/build-logos.mjs.
   Wide logos already spell the brand name, so they stand alone; square icons sit beside the name.
   Tools with no freely licensed logo show their name only, never a look-alike. */
type Entry = { file: string; ratio: number };
const table = logos as Record<string, Entry>;

export function ToolChip({ name }: { name: string }) {
  const logo = table[name];
  const wide = logo && logo.ratio > 1.3;
  return (
    <span className="flex h-11 items-center gap-2.5 rounded-full border border-line bg-white px-5 text-[15px] whitespace-nowrap text-[#16161a]">
      {logo && (
        <img
          src={logo.file}
          alt={wide ? name : ""}
          height={wide ? 20 : 20}
          width={Math.round(20 * logo.ratio)}
          className={wide ? "h-5 w-auto" : "h-5 w-5"}
          loading="lazy"
        />
      )}
      {!wide && name}
    </span>
  );
}
